function checkout(){
function makeFireOnGround() {
  const fireGeometry = new THREE.PlaneGeometry(5, 5); // Adjust size as needed
  const fireMaterial = new THREE.MeshStandardMaterial({
    color: 0xff4500, // Fire color
    emissive: 0xff4500,
    emissiveIntensity: 1,
    side: THREE.DoubleSide, // Fire should be visible from both sides
    transparent: true,
    opacity: 0.8 // Adjust for effect
  });

  const fireMesh = new THREE.Mesh(fireGeometry, fireMaterial);
  fireMesh.rotation.x = -Math.PI / 2; // Ensure fire lies flat on the ground
  fireMesh.position.set(0, 0.01, 0); // Slightly above ground to avoid z-fighting
  fireMesh.receiveShadow = true;
  fireMesh.castShadow = true;

  scene.add(fireMesh);
}

makeFireOnGround();
setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),2800);
}
